// Compiles content/blog/*.md into src/data/blogPosts.generated.ts.
// Runs before `dev` and `build` (package.json). Commit the generated file.
//
// Frontmatter: title, metaTitle, metaDescription, excerpt, publishedAt,
// updatedAt?, category, hub?, tags[], image, imageAlt?, featured?, tldr[], faq[{q,a}]
import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';
import { Marked } from 'marked';

const ROOT = path.resolve(import.meta.dirname, '..');
const SRC = path.join(ROOT, 'content/blog');
const OUT = path.join(ROOT, 'src/data/blogPosts.generated.ts');
const CATEGORIES = ['WhatsApp Automation', 'AI Agents & MCP', 'AI SEO & Content', 'Marketing & Growth', 'Developer Guides'];
const REQUIRED = ['title', 'metaTitle', 'metaDescription', 'excerpt', 'publishedAt', 'category', 'image', 'tldr'];

const slugify = (s) => s.toLowerCase().replace(/<[^>]+>/g, '').replace(/&[a-z]+;/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

const posts = fs.readdirSync(SRC).filter((f) => f.endsWith('.md')).sort().map((file) => {
  const slug = file.replace(/\.md$/, '');
  const { data, content } = matter(fs.readFileSync(path.join(SRC, file), 'utf8'));
  for (const key of REQUIRED) if (!data[key]) throw new Error(`${file}: missing frontmatter "${key}"`);
  if (!CATEGORIES.includes(data.category)) throw new Error(`${file}: unknown category "${data.category}"`);
  const date = (d) => (d instanceof Date ? d.toISOString().slice(0, 10) : String(d));

  // H2s get ids and feed the table of contents.
  const toc = [];
  const marked = new Marked({
    renderer: {
      heading({ tokens, depth }) {
        const text = this.parser.parseInline(tokens);
        const id = slugify(text);
        if (depth === 2) toc.push({ id, text: text.replace(/<[^>]+>/g, '') });
        return `<h${depth} id="${id}">${text}</h${depth}>\n`;
      },
      link({ href, title, tokens }) {
        const text = this.parser.parseInline(tokens);
        const external = /^https?:\/\//.test(href) && !href.startsWith('https://nexbotix.online');
        const attrs = external ? ' target="_blank" rel="noopener"' : '';
        return `<a href="${href}"${title ? ` title="${title}"` : ''}${attrs}>${text}</a>`;
      },
    },
  });
  const html = marked.parse(content);
  const words = content.split(/\s+/).filter(Boolean).length;

  return {
    slug,
    title: data.title,
    metaTitle: data.metaTitle,
    metaDescription: data.metaDescription,
    excerpt: data.excerpt,
    content: html,
    toc,
    tldr: data.tldr,
    faq: data.faq ?? [],
    publishedAt: date(data.publishedAt),
    updatedAt: date(data.updatedAt ?? data.publishedAt),
    readTime: `${Math.max(1, Math.round(words / 220))} min read`,
    wordCount: words,
    category: data.category,
    hub: data.hub ?? null,
    tags: data.tags ?? [],
    image: data.image,
    imageAlt: data.imageAlt ?? data.title,
    featured: Boolean(data.featured),
  };
}).sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));

const banner = '// GENERATED by scripts/build-blog.mjs from content/blog/*.md — do not edit.\n';
fs.writeFileSync(OUT, `${banner}import type { BlogPost } from './blogPosts';\n\nexport const BLOG_POSTS: BlogPost[] = ${JSON.stringify(posts, null, 2)};\n`);
console.log(`blog: ${posts.length} posts → ${path.relative(ROOT, OUT)}`);
